import math
class Solution:
    def minStable(self, nums: List[int], maxC: int) -> int:
        n = len(nums)
        sp = [nums[:]]
        j = 1
        while (1 << j) <= n:
            p = sp[-1]
            sp.append([math.gcd(p[i], p[i + (1 << (j-1))]) for i in range(n - (1 << j) + 1)])
            j += 1
        def qry(l, r):
            k = (r - l + 1).bit_length() - 1
            return math.gcd(sp[k][l], sp[k][r - (1 << k) + 1])
        def ok(L):
            if L >= n: return True
            cnt = 0; i = 0
            while i + L < n:
                if qry(i, i + L) >= 2:
                    cnt += 1
                    if cnt > maxC: return False
                    i = i + L + 1
                else:
                    i += 1
            return True
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid): hi = mid
            else: lo = mid + 1
        return lo

