class Solution {
public:
    int minStable(vector<int>& nums, int maxC) {
        int n = nums.size();
        vector<vector<int>> sp;
        sp.push_back(nums);
        for (int j = 1; (1 << j) <= n; j++) {
            auto& p = sp.back();
            vector<int> c(n - (1 << j) + 1);
            for (int i = 0; i < (int)c.size(); i++)
                c[i] = __gcd(p[i], p[i + (1 << (j-1))]);
            sp.push_back(c);
        }
        auto qry = [&](int l, int r) {
            int k = 31 - __builtin_clz(r - l + 1);
            return __gcd(sp[k][l], sp[k][r - (1 << k) + 1]);
        };
        auto ok = [&](int L) {
            if (L >= n) return true;
            int cnt = 0;
            for (int i = 0; i + L < n; ) {
                if (qry(i, i + L) >= 2) {
                    if (++cnt > maxC) return false;
                    i = i + L + 1;
                } else i++;
            }
            return true;
        };
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (ok(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

