class Solution {
    public int minStable(int[] nums, int maxC) {
        int n = nums.length;
        List<int[]> sp = new ArrayList<>();
        sp.add(nums.clone());
        for (int j = 1; (1 << j) <= n; j++) {
            int[] p = sp.get(sp.size() - 1);
            int[] c = new int[n - (1 << j) + 1];
            for (int i = 0; i < c.length; i++)
                c[i] = gcd(p[i], p[i + (1 << (j - 1))]);
            sp.add(c);
        }
        int[][] tab = sp.toArray(new int[0][]);
        java.util.function.BiFunction<Integer,Integer,Integer> qryF = (l, r) -> {
            int k = 31 - Integer.numberOfLeadingZeros(r - l + 1);
            return gcd(tab[k][l], tab[k][r - (1 << k) + 1]);
        };
        java.util.function.IntPredicate ok = L -> {
            if (L >= n) return true;
            int cnt = 0;
            for (int i = 0; i + L < n; ) {
                if (qryF.apply(i, i + L) >= 2) {
                    if (++cnt > maxC) return false;
                    i = i + L + 1;
                } else i++;
            }
            return true;
        };
        int lo = 0, hi = n;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (ok.test(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

