var minStable = function(nums, maxC) {
    const n = nums.length;
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    const sp = [nums.slice()];
    for (let j = 1; (1 << j) <= n; j++) {
        const p = sp[sp.length - 1], c = [];
        for (let i = 0; i + (1 << j) <= n; i++)
            c.push(gcd(p[i], p[i + (1 << (j - 1))]));
        sp.push(c);
    }
    const qry = (l, r) => {
        const k = 31 - Math.clz32(r - l + 1);
        return gcd(sp[k][l], sp[k][r - (1 << k) + 1]);
    };
    const ok = (L) => {
        if (L >= n) return true;
        let cnt = 0;
        for (let i = 0; i + L < n; ) {
            if (qry(i, i + L) >= 2) {
                if (++cnt > maxC) return false;
                i = i + L + 1;
            } else i++;
        }
        return true;
    };
    let lo = 0, hi = n;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (ok(mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
};
